const add=(parent,tag,text)=>{const x=document.createElement(tag);x.textContent=text;parent.append(x);return x};
try{const r=await fetch('/api/ops/access'),d=await r.json();if(!r.ok)throw Error(d.error);const dl=document.getElementById('readiness');for(const[k,v]of Object.entries({'運用モード':d.mode==='review'?'代表限定の検収中':'顧客別受付','顧客公開承認':d.clientReleaseApproved?'承認済み':'未承認・顧客受付なし','Google接続設定':d.storageConnected?'設定あり（保存結果は別途照合）':'未設定','保持期限':d.retentionPolicy==='AWAITING_OWNER_APPROVAL'?'代表決裁待ち':d.retentionPolicy,'バックアップ':'設定変更・削除前に手動実施'})){add(dl,'dt',k);add(dl,'dd',String(v))}for(const g of d.registry.grants){const tr=add(document.getElementById('access'),'tr','');for(const v of [g.userId,g.projectId,g.expiresAt,!g.enabled?'停止':Date.parse(g.expiresAt)<Date.now()?'期限切れ':'有効'])add(tr,'td',String(v))}if(!d.registry.grants.length)document.getElementById('empty').textContent='顧客アクセス設定は未登録です。';}catch(e){document.getElementById('opsError').textContent='運用情報を取得できません。'+e.message}
